-- Source: sql/analysis/10_analytical_views.sql
{{ config(materialized='view') }}

SELECT
  w.retail_week_key,
  w.retail_year,
  w.retail_week,
  w.retail_week_label,
  w.retail_half,
  w.is_comparable_week,
  st.store_key,
  st.store_id,
  st.store_name,
  st.region,
  st.store_format,
  a.sales_lines,
  a.units_sold,
  a.transactions,
  a.gross_sales,
  a.discount_value,
  a.sales_revenue,
  a.returns_value,
  a.net_revenue,
  a.cogs,
  a.gross_margin,
  a.promo_sales_revenue,
  a.late_arriving_sales_revenue,
  t.target_net_revenue,
  a.net_revenue - t.target_net_revenue AS variance_to_target,
  CAST(a.net_revenue AS DOUBLE) / NULLIF(CAST(t.target_net_revenue AS DOUBLE), 0) AS target_achievement_pct,
  CAST(a.sales_revenue AS DOUBLE) / NULLIF(CAST(a.transactions AS DOUBLE), 0) AS aov,
  CAST(a.units_sold AS DOUBLE) / NULLIF(CAST(a.transactions AS DOUBLE), 0) AS upt,
  CAST(a.sales_revenue AS DOUBLE) / NULLIF(CAST(a.units_sold AS DOUBLE), 0) AS asp,
  CAST(a.gross_margin AS DOUBLE) / NULLIF(CAST(a.net_revenue AS DOUBLE), 0) AS gross_margin_pct
FROM (
  SELECT
    d.retail_week_key,
    p.store_key,
    SUM(p.sales_lines) AS sales_lines,
    SUM(p.units_sold) AS units_sold,
    SUM(p.transactions) AS transactions,
    SUM(p.gross_sales) AS gross_sales,
    SUM(p.discount_value) AS discount_value,
    SUM(p.sales_revenue) AS sales_revenue,
    SUM(p.returns_value) AS returns_value,
    SUM(p.net_revenue) AS net_revenue,
    SUM(p.cogs) AS cogs,
    SUM(p.gross_margin) AS gross_margin,
    SUM(p.promo_sales_revenue) AS promo_sales_revenue,
    SUM(p.late_arriving_sales_revenue) AS late_arriving_sales_revenue
  FROM {{ ref('v_performance_store_day') }} AS p
  JOIN {{ ref('dim_date') }} AS d
    ON d.date_key = p.date_key
  GROUP BY
    d.retail_week_key,
    p.store_key
) AS a
JOIN {{ ref('dim_retail_week') }} AS w
  ON w.retail_week_key = a.retail_week_key
JOIN {{ ref('dim_store') }} AS st
  ON st.store_key = a.store_key
LEFT JOIN {{ ref('fact_targets') }} AS t
  ON t.retail_week_key = a.retail_week_key AND t.store_key = a.store_key
